    ...(selection.bodySha256===undefined?{}:{bodySha256:selection.bodySha256,bodyBytes:selection.bodyBytes}),
    ...(ticketFile === undefined ? {} : {ticketFile}), ...(ticketHeader === undefined ? {} : {ticketHeader})});
