/** Original file-based CLI; output remains private, create-only and fsynced. */
export async function prepare(args) {
  need(args.length >= required.length * 2 && args.length % 2 === 0, 'PREPARE_EXPLICIT_SELECTION_REQUIRED');
  const flags = new Map();
