  const address = process.platform === 'win32'
    ? '\\\\.\\pipe\\' + name : join(directory, filename.replace(/\.lock$/, '.sock'));
  const server = createServer(socket => socket.destroy());
  try {
    await new Promise((accept, reject) => {
      const failed = error => {
        server.close(() => {});
        reject(new InputError(error.code === 'EADDRINUSE' ? busyCode : unavailableCode));
      };
      server.once('error', failed);
      server.listen(address, () => { server.off('error', failed); accept(); });
    });
  } catch (error) {
    server.close(() => {});
    if (error instanceof InputError) throw error;
    throw new InputError(unavailableCode);
  }
  server.unref();
  let released;
  return () => released ??= new Promise((accept, reject) =>
    server.close(error => error ? reject(error) : accept()));
}

#!/usr/bin/env node
// MIT — Exact-intent operator commands; no automatic scheduling or paid retry.
import { initializeQueue, openQueue, saveQueueReport } from './queue.mjs';
import { need } from './config.mjs';

const print = value => process.stdout.write(JSON.stringify(value, null, 2) + '\n');
const commands = {init:[], enqueue:['--config'], list:[], show:['--intent'],
  execute:['--intent'], recover:['--intent'], finalize:['--intent','--workspace'], cancel:['--intent'], report:['--out'],
  'inspect-lost-output':['--intent','--workspace','--approved-request'],
  'read-lost-output':['--intent','--workspace'],
  'export-lost-output':['--intent','--workspace','--out'],
  'recover-lost-output':['--intent','--workspace','--transaction','--request-sha','--approved-request'],
  'inspect-missing-receipt':['--intent','--workspace'],
  'read-missing-receipt':['--intent','--workspace'],
  'recover-missing-receipt':['--intent','--workspace','--transaction','--request-sha']};
let signalExit;
async function main(args) {
  if (args[0] === 'operations') {
    const {main: operationsHandoff} = await import('./operations-handoff/cli.mjs');
    return operationsHandoff(args.slice(1));
  }
  if (args[0] === 'review-jobs') {
    const {main: reviewJobs} = await import('./review-jobs/cli.mjs');
    return reviewJobs(args.slice(1));
  }
  if (args[0] === 'library') {
    const {main: resourceLibrary} = await import('./resource-library/cli.mjs');
    return resourceLibrary(args.slice(1));
  }
  if (args.length === 1 && args[0] === '--help') {
    process.stdout.write('Usage: node queue-cli.mjs COMMAND --root /absolute/inbox [OPTION VALUE]\n' +
      'Commands: init | enqueue --config ABS | list | show --intent ID | execute --intent ID [--workspace ABS] | recover --intent ID | finalize --intent ID --workspace ABS [--outbox ABS --merchant-route ID] | cancel --intent ID | report --out ABS [--workspace ABS]\n' +
      'Missing receipt: inspect-missing-receipt | read-missing-receipt | recover-missing-receipt --transaction HASH --request-sha HASH; each requires --intent ID --workspace ABS. Read/recover accept --attempt ID --config-sha HASH --node ABS.\n' +
      'Lost local output: inspect-lost-output --approved-request ABS | read-lost-output | recover-lost-output --transaction HASH --request-sha HASH --approved-request ABS; each requires --intent ID --workspace ABS.\n' +
      'Operations source: operations export --inbox ABS --intent ID [--intent ID ...] --output ABS [--max-verify-bytes N] | operations inspect --file ABS. No buyer execution.\n' +
      'Delivered resources: library --help (search, preview, download and retain analyst reviews).\n' +
      'Customer review jobs: review-jobs --help (source, native request, review, delivery and recovery).\n' +
      'Execute invokes the original SF88 operator approval for one exact intent. An attempted intent is never replayed.\n');
    return;
  }
  const [command, ...rest] = args;
  need(Object.hasOwn(commands, command), 'INBOX_COMMAND_REQUIRED');
  const required = ['--root', ...commands[command]];
  const allowed = [...required, ...(['execute','report'].includes(command) ? ['--workspace'] : []),
    ...(command === 'finalize' ? ['--outbox','--merchant-route'] : []),
    ...(['read-missing-receipt','recover-missing-receipt','read-lost-output','recover-lost-output'].includes(command)?['--attempt','--config-sha','--node']:[]),
    ...(['read-missing-receipt','read-lost-output'].includes(command)?['--request-sha']:[])], flags = new Map();
  need(rest.length % 2 === 0 && rest.length >= required.length * 2 &&
    rest.length <= allowed.length * 2, 'INBOX_EXPLICIT_ARGUMENTS_REQUIRED');
  for (let i=0; i<rest.length; i+=2) {
    need(allowed.includes(rest[i]) && !flags.has(rest[i]) && typeof rest[i+1] === 'string', 'INBOX_ARGUMENT_INVALID');
    flags.set(rest[i], rest[i+1]);
  }
  need(required.every(flag => flags.has(flag)), 'INBOX_EXPLICIT_ARGUMENTS_REQUIRED');
  if (command === 'init') return print(await initializeQueue(flags.get('--root')));
  const queue = await openQueue(flags.get('--root'));
  if (command === 'enqueue') return print(await queue.enqueue(flags.get('--config')));
  if (command === 'list') return print(await queue.list());
  if (command === 'show') return print(await queue.show(flags.get('--intent')));
  if (command === 'recover') return print(await queue.recover(flags.get('--intent')));
  if (command === 'cancel') return print(await queue.cancel(flags.get('--intent')));
  if (command === 'inspect-lost-output') {
    const {inspectLostOutputAttempt}=await import('./lost-output.mjs');
    return print(await inspectLostOutputAttempt({root:queue.root,intentId:flags.get('--intent'),
      workspace:flags.get('--workspace'),approvedRequestFile:flags.get('--approved-request')}));
  }
  if (command === 'inspect-missing-receipt') {
    const {inspectMissingReceiptAttempt}=await import('./missing-receipt.mjs');
    return print(await inspectMissingReceiptAttempt({root:queue.root,intentId:flags.get('--intent'),
      workspace:flags.get('--workspace')}));
  }
  if (command === 'report') {
    const {renderQueueReport} = await import('./queue-report.mjs');
    const {readLostOutputQueueViews} = await import('./lost-output.mjs');
    return print(await saveQueueReport(flags.get('--out'), renderQueueReport({
      jobs:await readLostOutputQueueViews({root:queue.root,workspace:flags.get('--workspace')}),
      queueRoot:queue.root, accountingWorkspace:flags.get('--workspace'),
    })));
  }
  const controller = new AbortController();
  const interrupt = () => { signalExit = 130; controller.abort(); };
  const terminate = () => { signalExit = 143; controller.abort(); };
  process.on('SIGINT', interrupt); process.on('SIGTERM', terminate);
  try {
    let result;
    if(['read-lost-output','recover-lost-output','export-lost-output'].includes(command)) {
      const api=await import('./lost-output.mjs');
      const operation=command==='read-lost-output'?api.readLostOutputRecovery:
        command==='export-lost-output'?api.exportLostOutputProof:api.recoverLostOutput;
      result=await operation({root:queue.root,intentId:flags.get('--intent'),workspace:flags.get('--workspace'),
        transaction:flags.get('--transaction'),expectedRequestSha256:flags.get('--request-sha'),
        approvedRequestFile:flags.get('--approved-request'),output:flags.get('--out'),expectedAttemptId:flags.get('--attempt'),
        expectedConfigSha256:flags.get('--config-sha'),node:flags.get('--node'),signal:controller.signal});
    } else if(['read-missing-receipt','recover-missing-receipt'].includes(command)) {
      const api=await import('./missing-receipt.mjs');
      const operation=command==='read-missing-receipt'?api.readMissingReceiptRecovery:api.recoverMissingReceipt;
      result=await operation({root:queue.root,intentId:flags.get('--intent'),workspace:flags.get('--workspace'),
        transaction:flags.get('--transaction'),expectedRequestSha256:flags.get('--request-sha'),
        expectedAttemptId:flags.get('--attempt'),expectedConfigSha256:flags.get('--config-sha'),
        node:flags.get('--node'),signal:controller.signal});
    } else if(command === 'finalize') {
      const {finalizeQueueIntent}=await import('./finalization.mjs');
      result=await finalizeQueueIntent({root:queue.root,intentId:flags.get('--intent'),
        workspace:flags.get('--workspace'),outbox:flags.get('--outbox'),
        merchantRoute:flags.get('--merchant-route'),signal:controller.signal});
      if(!['FINALIZED','IDEMPOTENT_FINALIZED'].includes(result.finalization?.result?.outcome)||
        result.finalizationView?.status!=='SAVED')process.exitCode=2;
    } else result = await queue.run(flags.get('--intent'), {signal:controller.signal,
      ...(flags.has('--workspace') ? {workspace:flags.get('--workspace')} : {})});
    print(result);
    if (!command.endsWith('-missing-receipt')&&!command.endsWith('-lost-output')&&result?.lastError) process.exitCode = 2;
  } finally {
    process.off('SIGINT', interrupt); process.off('SIGTERM', terminate);
    if (signalExit !== undefined) process.exitCode = signalExit;
  }
}
main(process.argv.slice(2)).catch(error => {
  const code = /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '') ? error.code : 'INBOX_OPERATION_FAILED';
  process.stderr.write(JSON.stringify({error:code, retry:'NO_AUTOMATIC_RETRY'}) + '\n');
  process.exitCode = signalExit ?? 1;
});

// MIT — Deliver selected original SF88 response files through original SF100.
import {createHash} from 'node:crypto';
import {constants} from 'node:fs';
import {open, mkdir, lstat, realpath, rm} from 'node:fs/promises';
import {basename, dirname, isAbsolute, join, resolve} from 'node:path';
import {isDeepStrictEqual} from 'node:util';
import {openQueue} from './queue.mjs';
import {InputError, need, config, execution} from './config.mjs';
import {inspectDatasetPage, bindDatasetResponseMetadata} from './dataset-page.mjs';
import {aggregateOutcomes} from '../sf52-buyer-outcomes/outcomes.mjs';
import {init, appendMany, finalize} from '../sf100-buyer-dataset-delivery/deliver.mjs';

const MAX_PAGE = 2 * 1024 * 1024;
const MAX_SOURCES = 256 * 1024 * 1024;
const MAX_PAGES = 4096;
const INTENT = /^[A-Za-z0-9._:-]{1,128}$/;
const HASH = /^[a-f0-9]{64}$/;
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const privateMode = info => process.platform === 'win32' || ((info.mode & 0o077) === 0 &&
  (typeof process.getuid !== 'function' || info.uid === process.getuid()));
const pathOf = value => {
  need(typeof value === 'string' && isAbsolute(value) && !value.includes('\0'),
    'DATASET_ABSOLUTE_PATH_REQUIRED');
  return resolve(value);
};

async function privateDirectory(path) {
  const info = await lstat(path);
  need(info.isDirectory() && !info.isSymbolicLink() && privateMode(info) &&
    await realpath(path) === path, 'DATASET_PRIVATE_DIRECTORY_REQUIRED');
  return info;
}

async function readPrivate(path, limit) {
  const handle = await open(pathOf(path), constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const info = await handle.stat();
    need(info.isFile() && privateMode(info) && info.size <= limit, 'DATASET_PRIVATE_FILE_REQUIRED');
    const bytes = await handle.readFile();
    need(bytes.length <= limit, 'DATASET_SOURCE_BYTE_LIMIT');
    return bytes;
  } finally { await handle.close(); }
}

async function writePrivate(path, bytes) {
  const handle = await open(path, 'wx', 0o600);
  try { await handle.writeFile(bytes); await handle.sync(); }
  finally { await handle.close(); }
  return {sha256:sha(bytes), bytes:bytes.length};
}

function select(intents) {
  need(Array.isArray(intents) && intents.length > 0 && intents.length <= MAX_PAGES &&
    intents.every(id => typeof id === 'string' && INTENT.test(id)) &&
    new Set(intents).size === intents.length, 'DATASET_EXPLICIT_UNIQUE_INTENTS_REQUIRED');
  return [...intents];
}

export async function readDatasetSelection(path) {
  const raw = await readPrivate(path, 1024 * 1024);
  let value;
  try { value = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
  catch { throw new InputError('DATASET_SELECTION_JSON_INVALID'); }
  return select(value);
}

function requestOf(record) {
  need(record.operation.method === 'GET' && record.bodySha256 === null,
    'DATASET_ORIGINAL_GET_REQUIRED');
  const url = new URL(record.operation.url), keys = new Set();
  const query = [];
  let cursor;
  for (const [key, value] of url.searchParams) {
    need(!keys.has(key), 'DATASET_REPEATED_REQUEST_PARAMETER');
    keys.add(key);
    if (key === 'cursor') cursor = value;
    else if (key !== 'limit') query.push([key, value]);
  }
  query.sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
  // Page size may change; the original endpoint, projection and query must not.
  return {identity:JSON.stringify([url.origin, url.pathname, query]), cursor};
}

async function savedPage(queue, intentId) {
  const record = await queue.show(intentId);
  const outcome = record.outcome, saved = outcome?.responseFile;
  need(record.attempt?.kind === 'EXECUTE' &&
    outcome?.mode === 'ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT' &&
    outcome.intentId === intentId && saved?.status === 'SAVED' &&
    Number.isInteger(outcome.httpStatus) && outcome.httpStatus >= 200 && outcome.httpStatus < 300 &&
    HASH.test(saved.sha256) && Number.isSafeInteger(saved.bytes) && saved.bytes >= 0 &&
    saved.bytes <= MAX_PAGE && typeof record.responseDestination === 'string',
    'DATASET_ORIGINAL_SAVED_RESPONSE_REQUIRED');
  const configured = pathOf(record.responseDestination);
  const canonical = join(await realpath(dirname(configured)), basename(configured));
  need(saved.path === canonical, 'DATASET_RESPONSE_DESTINATION_MISMATCH');
  const response = await readPrivate(saved.path, MAX_PAGE);
  need(response.length === saved.bytes && sha(response) === saved.sha256,
    'DATASET_ORIGINAL_RESPONSE_CHANGED');
  let evidence = null, evidenceDigestSource = null;
  if (outcome.evidencePath !== null && outcome.evidencePath !== undefined) {
    need(outcome.evidencePath === record.evidencePath, 'DATASET_EVIDENCE_DESTINATION_MISMATCH');
    evidence = await readPrivate(outcome.evidencePath, MAX_PAGE);
    let original;
    try { original = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(evidence)); }
    catch { throw new InputError('DATASET_ORIGINAL_EVIDENCE_INVALID'); }
    need(original?.schema === 'scf82.checkout-evidence.v1' && original.intentId === intentId &&
      original.observation?.intentId === intentId && original.observedAt === original.observation.observedAt &&
      Number.isFinite(Date.parse(original.observedAt)) &&
      Date.parse(original.observedAt) >= Date.parse(record.attempt.startedAt),
      'DATASET_ORIGINAL_EVIDENCE_MISMATCH');
    // SF52's generatedAt is the report-generation time, not an observed event.
    // Compare its actual contents while preserving both original timestamps.
    const {generatedAt: regeneratedAt, ...computed} = aggregateOutcomes([original.observation]);
    const {generatedAt: originalGeneratedAt, ...retained} = outcome.originalOutcomeReport ?? {};
    need(isDeepStrictEqual(computed, retained),
      'DATASET_ORIGINAL_EVIDENCE_OUTCOME_CHANGED');
    if (record.recovery) {
      need(HASH.test(record.recovery.evidenceSha256) && sha(evidence) === record.recovery.evidenceSha256,
        'DATASET_RECOVERED_EVIDENCE_CHANGED');
      evidenceDigestSource = 'RECORDED_BY_ORIGINAL_INBOX_RECOVERY';
    } else evidenceDigestSource = 'CAPTURED_DURING_DATASET_EXPORT';
  }
  return {record, response, evidence, evidenceDigestSource, request:requestOf(record)};
}

/** A new private package, assembled only from explicit, already-saved attempts.
 * Original SF100 validates page/query/cursor continuity and writes the dataset.
 * This function never executes a buyer, imports a signer, or opens its ledger. */
export async function exportQueueDataset({root, intents, destination} = {}) {
  const selection = select(intents), out = pathOf(destination);
  await privateDirectory(dirname(out));
  const queue = await openQueue(root);
  // mkdir is the destination claim. An existing directory is never replaced.
  await mkdir(out, {mode:0o700});
  const created = await privateDirectory(out);
  let finished = false;
  try {
    const sources = join(out, 'sources'), dataset = join(out, 'dataset');
    await mkdir(sources, {mode:0o700});
    await init(dataset);
    const operations = [], inputs = [];
    let sourceBytes = 0, requestIdentity = null, previous = null;
    for (let index = 0; index < selection.length; index++) {
      const intentId = selection[index];
      const {record, response, evidence, evidenceDigestSource, request} = await savedPage(queue, intentId);
      let page = inspectDatasetPage(response, {url:record.operation.url, previous});
      if (page.semantics) {
        const executionPath = join(queue.root, 'jobs', record.id, 'execution.json');
        const raw = await readPrivate(executionPath, 65536);
        need(sha(raw) === record.configSha256, 'DATASET_ORIGINAL_CONFIG_CHANGED');
        const cfg = await config(executionPath);
        need(isDeepStrictEqual(execution(cfg).op, record.operation) &&
          join(cfg.evidenceDir, record.id + '.json') === record.evidencePath,
          'DATASET_ORIGINAL_CONFIG_CHANGED');
        page = await bindDatasetResponseMetadata(page, cfg,
          {status:record.outcome.httpStatus, nativeBuyerStatus:record.outcome.status});
      }
      previous = page;
      const operationBytes = encode(record);
      sourceBytes += response.length + operationBytes.length + (evidence?.length ?? 0);
      need(sourceBytes <= MAX_SOURCES, 'DATASET_SOURCE_BYTE_LIMIT');
      if (index === 0) {
        need(request.cursor === undefined, 'DATASET_FIRST_REQUEST_HAS_CURSOR');
        requestIdentity = request.identity;
      } else need(request.identity === requestIdentity, 'DATASET_REQUEST_QUERY_CHANGED');
      const prefix = String(index).padStart(5, '0');
      const sourcePath = 'sources/' + prefix + '.response.json';
      const operationPath = 'sources/' + prefix + '.operation.json';
      const evidencePath = evidence === null ? null : 'sources/' + prefix + '.evidence.json';
      const sourceFile = await writePrivate(join(out, sourcePath), response);
      const operationFile = await writePrivate(join(out, operationPath), operationBytes);
      const evidenceFile = evidence === null ? null : await writePrivate(join(out, evidencePath), evidence);
      operations.push({index, intentId, inboxRecord:record.id, attemptId:record.attempt.id,
        configSha256:record.configSha256,
        source:{path:sourcePath, ...sourceFile},
        originalOperation:{path:operationPath, ...operationFile},
        evidence:evidenceFile === null ? null : {path:evidencePath, ...evidenceFile, digestSource:evidenceDigestSource},
        ...(page.semantics ? {semantics:page.semantics,
          semanticResponseHeaders:page.semanticResponseHeaders,
          semanticResponseRecord:page.semanticResponseRecord} : {})});
      inputs.push({page:join(out, sourcePath), intent:intentId,
        ...(request.cursor === undefined ? {} : {cursor:request.cursor}),
        ...(evidencePath === null ? {} : {evidence:join(out, evidencePath)})});
    }
    await appendMany(dataset, inputs);
    const delivery = await finalize(dataset);
    const nativeManifest = await readPrivate(join(dataset, 'manifest.json'), 8 * 1024 * 1024);
    const dictionary = delivery.semantics ? {
      file:'dataset/semantics.json', ...delivery.outputs['semantics.json'],
      semanticSha256:delivery.semantics.sha256,
      definitionSha256:delivery.semantics.definitionSha256,
      captureManifestSha256:delivery.semantics.captureManifestSha256,
    } : null;
    const manifest = {schema:'stellar-forge.sf88.queue-dataset-delivery.v1',
      createdAt:new Date().toISOString(), queueRoot:queue.root,
      selection:{intents:selection, sha256:sha(encode(selection))},
      originalDatasetManifest:{path:'dataset/manifest.json', sha256:sha(nativeManifest), bytes:nativeManifest.length},
      operations, dataset:{name:delivery.dataset, snapshot:delivery.snapshot,
        pages:delivery.pages, rows:delivery.rows, total:delivery.total},
      ...(dictionary ? {semanticDictionary:dictionary} : {}),
    };
    // Completion is published last. A process interruption leaves an explicitly
    // incomplete local directory; the original inbox and saved files are intact.
    const completion = await writePrivate(join(out, 'delivery.json'), encode(manifest));
    finished = true;
    return {action:'DATASET_DELIVERED', directory:out,
      manifest:{path:join(out, 'delivery.json'), ...completion},
      review:join(dataset, 'review.html'), jsonl:join(dataset, 'dataset.jsonl'), csv:join(dataset, 'dataset.csv'),
      ...manifest.dataset, operations:operations.length,
      ...(dictionary ? {semanticDictionary:{path:join(out,dictionary.file),...dictionary}} : {})};
  } finally {
    if (!finished) {
      const current = await lstat(out).catch(() => null);
      // Remove only this invocation's new failed package, never an input or a
      // replacement destination. Abrupt process termination remains visible.
      if (current?.isDirectory() && !current.isSymbolicLink() &&
        current.dev === created.dev && current.ino === created.ino)
        await rm(out, {recursive:true, force:true}).catch(() => {});
    }
  }
}

// MIT — SF88 private, offline cross-intent history. Original buyer results remain authoritative.
// Pure renderer: no filesystem, network, signer, payment or ledger operation.

const STATES = [
  ['QUEUED', 'Queued'],
  ['RUNNING_OR_INTERRUPTED', 'Running or interrupted'],
  ['ATTEMPT_RECORDED', 'Attempt recorded'],
  ['RECOVERED', 'Evidence recovered'],
  ['CANCELLED', 'Cancelled'],
  ['REVIEW_REQUIRED', 'Local record needs review'],
];
const LABELS = new Map(STATES);
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = (value, fallback = 'Not recorded') => {
  if (value === null || value === undefined || value === '') return fallback;
  if (!['string', 'number', 'boolean', 'bigint'].includes(typeof value)) return fallback;
  return String(value);
};
const escape = value => text(value, '').replace(/[&<>"']/g, c => ({
  '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;',
}[c]));
const code = value => `<code>${escape(text(value))}</code>`;
const field = (label, value) => `<div><dt>${escape(label)}</dt><dd>${code(value)}</dd></div>`;
const fields = values => `<dl>${values.map(([label, value]) => field(label, value)).join('')}</dl>`;
const section = (title, content) => `<section class="section"><h3>${escape(title)}</h3>${content}</section>`;
const shellQuote = value => "'" + String(value).replace(/'/g, "'\\''") + "'";
const command = (verb, root, intentId) =>
  `node stellar/scf-starforge-20261009/sf88-operator-buyer-cli/queue-cli.mjs ${verb} --root ${shellQuote(root)} --intent ${shellQuote(intentId)}`;
const nativeSummary = job => object(job.outcome) ? job.outcome : {};
const recoveryOf = job => object(job.recovery) ? job.recovery : {};
const intentOf = job => text(job.operation?.intentId ?? job.id);

function reportOutcome(job) {
  const recovered = recoveryOf(job);
  const summary = nativeSummary(job);
  const report = recovered.report ?? recovered.originalOutcomeReport ?? summary.originalOutcomeReport;
  if (!Array.isArray(report?.outcomes)) return null;
  return report.outcomes.find(value => object(value) && value.intentId === intentOf(job)) ?? null;
}

function errorFields(job) {
  const original = nativeSummary(job);
  const storedError = job.lastError ?? job.error;
  const error = object(storedError) ? storedError : typeof storedError === 'string' ? {code:storedError} : {};
  const rows = [
    ['Queue error', error.code],
    ['Queue failure payment-sent state', error.paymentSent === null ? 'Unknown' : error.paymentSent],
    ['Queue failure interruption state', error.interrupted],
    ['Original buyer error', original.error?.code],
    ['Payment sent, as reported by the original buyer', original.error?.paymentSent],
    ['Original evidence error', original.evidenceError?.code],
    ['Response cleanup error', original.responseCleanupError?.code],
    ['Interrupted', original.interrupted],
  ].filter(([, value]) => value !== undefined && value !== null);
  return rows.length ? section('Recorded errors and interruption', fields(rows)) : '';
}

function responseDetails(summary, title = 'Response file') {
  const output = summary.responseFile;
  if (!object(output)) return section(title, '<p>File saving was not recorded for this attempt.</p>');
  const rows = [
    ['Status', output.status], ['Destination', output.destination ?? output.path],
    ['Saved path', output.path], ['Bytes', output.bytes], ['SHA-256', output.sha256],
    ['Content type', output.contentType], ['Partial path', output.partialPath],
    ['Failure code', output.code], ['Reason', output.reason], ['Cleanup error', output.cleanupError],
  ].filter(([, value]) => value !== undefined && value !== null);
  const warnings = Array.isArray(output.cleanupWarnings) ? output.cleanupWarnings.filter(object) : [];
  const warningHtml = warnings.length ? '<h4>Cleanup warnings</h4><ul>' + warnings.map(w =>
    `<li>${code(w.code)}${w.path ? ' — ' + code(w.path) : ''}</li>`).join('') + '</ul>' : '';
  return section(title, fields(rows) + warningHtml +
    (output.status === 'REQUIRES_ORIGINAL_DOWNLOAD_SUMMARY' ?
      '<p class="note">Recovery did not inspect this file or establish its bytes, hash, or completeness. Use the original download summary.</p>' :
      '<p class="note">A saved file describes local delivery. A failed or partial file does not undo an attempted payment.</p>'));
}

function recoveryDetails(job) {
  const recovery = recoveryOf(job);
  if (!Object.keys(recovery).length) return '';
  const metadata = object(recovery.evidence) ? recovery.evidence : recovery;
  const rows = [
    ['Recovery status', recovery.status], ['Recovered at', recovery.recoveredAt],
    ['Evidence schema', metadata.evidenceSchema], ['Evidence path', metadata.evidencePath ?? metadata.path],
    ['Evidence SHA-256', metadata.evidenceSha256 ?? metadata.sha256],
    ['Original observation time', metadata.observedAt], ['Original observation status', metadata.observationStatus],
    ['Reconciliation record', recovery.reconciliation?.status ?? metadata.reconciliationStatus],
    ['Body capture', recovery.bodyCapture?.status ?? metadata.bodyCaptureStatus],
    ['Evidence binding', recovery.binding],
  ].filter(([, value]) => value !== undefined && value !== null);
  return section('Recovered original evidence', fields(rows) +
    '<p class="note">Recovery reads the original saved checkout evidence. The financial-finalization command separately matches its complete approved request to this inbox and the existing spending ledger. Inspect the recorded binding and file-save outcome; reading evidence does not repeat the purchase.</p>');
}

function finalizationDetails(job) {
  const saved=job.lostOutputFinalization??job.finalization;
  if(!object(saved))return section('Accounting',job.lostOutputFinalizationError?
    fields([['Recovered accounting read',job.lostOutputFinalizationError]]):
    '<p>No financial-finalization result has been saved in this inbox.</p>');
  const result=object(saved.result)?saved.result:{};
  const last=object(saved.lastFinalized)?saved.lastFinalized:null;
  const rows=[
    ['Latest accounting result',result.outcome],['Checked at',saved.completedAt],
    ['Actual atomic units',result.actual],['Canonical transaction receipt',result.receipt_ref],
    ['Approved request SHA-256',saved.approvedRequestSha256??saved.requestSha256],['Finality proof SHA-256',result.proof_sha256],
    ['Chain observation',result.chainObservation],['Failure reason',result.reason],
    ['Merchant notification',result.merchant?.status],['Merchant order',result.merchant?.orderReference],
    ['Callback state',result.merchant?.callbackState],
    ['Recovered original attempt',job.lostOutputFinalization?.attemptId],
    ['Original output state',job.lostOutputFinalization?.evidenceState?.condition],
    ['Original output SHA-256',job.lostOutputFinalization?.evidenceState?.sha256],
    ['Recovery record authority',job.lostOutputFinalization?.recordAuthority],
    ['Recovered accounting read',job.lostOutputFinalizationError],
    ['Earlier finalized result',last&&last.completedAt!==saved.completedAt?last.result?.outcome:undefined],
    ['Earlier finalization time',last&&last.completedAt!==saved.completedAt?last.completedAt:undefined],
  ].filter(([,value])=>value!==undefined&&value!==null);
  return section('Accounting',fields(rows)+
    '<p class="note">This is the saved result from the original spending ledger. Repeating finalization checks or reuses that same transaction; it does not make another purchase. Merchant notification and completed file delivery remain separate outcomes.</p>');
}

function dependencyDetails(job) {
  if (!object(job.dependencies) && !Array.isArray(job.dependencies)) return '';
  const records = Array.isArray(job.dependencies) ? job.dependencies.map((item,index) => [item?.role ?? `File ${index + 1}`,item]) :
    Object.entries(job.dependencies);
  const rows = records.flatMap(([label, value]) => object(value) ? [
    [`${label}: file`, value.path ?? value.originalPath],
    [`${label}: SHA-256`, value.sha256 ?? value.digest],
  ].filter(([, fieldValue]) => fieldValue !== undefined) : []);
  return rows.length ? section('Pinned operator files', fields(rows) +
    '<p class="note">The queue checks these file identities before the original buyer runs. The live original policy still controls spending.</p>') : '';
}

function detail(job, queueRoot, commandFor, accountingWorkspace) {
  const op = object(job.operation) ? job.operation : {};
  const terms = object(op.expect) ? op.expect : {};
  const original = nativeSummary(job);
  const observed = reportOutcome(job);
  const recovery = recoveryOf(job);
  const reservation = original.operatorReservation ?? recovery.operatorReservation ?? {};
  const reviewed = section('Saved request', fields([
    ['Stable intent', intentOf(job)], ['Method', op.method], ['Resource URL', op.url],
    ['Network', terms.network], ['Asset', terms.asset], ['Recipient', terms.payTo],
    ['Maximum atomic units', terms.maxAtomic], ['Maximum timeout, seconds', terms.maxTimeoutSeconds],
    ['Configuration SHA-256', job.configSha256], ['Request body SHA-256', job.bodySha256],
    ['Original configuration SHA-256', job.sourceConfigSha256],
    ['Request body bytes', job.bodyBytes], ['Configured response destination', job.responseDestination],
    ['Queued at', job.createdAt],
  ]));
  const attempt = section('Local attempt', fields([
    ['Queue state', job.state], ['Attempt identifier', job.attempt?.id],
    ['Attempt started', job.attempt?.startedAt],
    ['Original reservation identifier', reservation.request_id ?? reservation.requestId],
    ['Original reservation state', reservation.outcome],
    ['Reserved atomic units', reservation.reserved_atomic_units ?? reservation.reservedAtomicUnits],
    ['Original evidence path', original.evidencePath ?? recovery.evidencePath],
  ]));
  const result = section('Original buyer and chain outcome', fields([
    ['Original buyer status', original.status], ['Original HTTP status', original.httpStatus],
    ['Seller-reported settlement', typeof original.sellerReportedSettlement === 'string' ?
      original.sellerReportedSettlement : original.sellerReportedSettlement?.success],
    ['Original SF52 classification', observed?.status],
    ['Signed attempt', observed?.signedAttempt],
    ['Independently verified transfer', observed?.independentlyVerifiedTransfer],
    ['HTTP body observed by the evidence adapter', observed?.observedHttpBody],
    ['Original chain evidence', observed?.chainEvidence], ['Ledger', observed?.ledger],
    ['Original retry policy', original.retry],
  ]) + '<p class="note">Atomic units stay grouped by their original asset and network. Queue activity, HTTP delivery, and a seller receipt are not booked revenue.</p>');
  const action = job.state === 'QUEUED' ? 'execute' : 'recover';
  const actionCopy = job.state === 'REVIEW_REQUIRED' ?
    'This saved record could not be read consistently. Inspect its original private files and the recorded error before using the operation.' : job.state === 'CANCELLED' ?
    'This request was cancelled locally before a queue execution. Its original saved identity remains in history.' : job.state === 'QUEUED' ?
    'To run this exact queued request, use the trusted terminal. The original buyer still obtains fresh terms and operator approval.' :
    'Inspect this attempt and recover any original terminal evidence before deciding what happened. The permanent attempt marker prevents another queue execution.';
  const workspace=accountingWorkspace??job.lostOutputFinalization?.workspace??job.finalization?.workspace;
  const accountingVerb=job.lostOutputFinalization?'read-lost-output':'finalize';
  const finalizeCommand=job.attempt?.kind==='EXECUTE'&&typeof workspace==='string'&&workspace?
    command(accountingVerb,queueRoot,intentOf(job))+' --workspace '+shellQuote(workspace):null;
  const actions = section('Operator commands', `<p>${escape(actionCopy)}</p>` +
    `<h4>Inspect saved history</h4><pre>${escape(commandFor('show', queueRoot, intentOf(job)))}</pre>` +
    (!['CANCELLED','REVIEW_REQUIRED'].includes(job.state) ? `<h4>${action === 'execute' ? 'Execute this one intent' : 'Read original evidence'}</h4><pre>${escape(commandFor(action, queueRoot, intentOf(job)))}</pre>` : '') +
    (finalizeCommand?`<h4>${job.lostOutputFinalization?'Read recovered payment accounting':'Finalize original payment accounting'}</h4><pre>${escape(finalizeCommand)}</pre>`:'')+
    '<p class="note">These are copyable commands only. This report has no execution controls and contacts no service.</p>');
  const recoveredFile = object(recovery.deliveryFile) ?
    responseDetails({responseFile:recovery.deliveryFile}, 'Response-file recovery status') : '';
  return `<div class="detail-grid">${reviewed}${dependencyDetails(job)}${attempt}${result}${finalizationDetails(job)}${responseDetails(original)}${recoveryDetails(job)}${recoveredFile}${errorFields(job)}${actions}</div>`;
}

function row(job, index, queueRoot, commandFor, accountingWorkspace) {
  const intent = intentOf(job);
  const original = nativeSummary(job);
  const observed = reportOutcome(job);
  const recovery = recoveryOf(job);
  const output = original.responseFile ?? recovery.deliveryFile;
  const state = text(job.state);
  const id = `intent-${index + 1}`;
  const search = [intent, job.operation?.url, job.operation?.method, state,
    job.operation?.expect?.asset, job.operation?.expect?.network,
    original.status, observed?.status, original.error?.code].map(value => text(value, '')).join(' ').toLowerCase();
  const outcome = observed?.status ?? recovery.observationStatus ?? original.status;
  const accounting=(job.lostOutputFinalization??job.finalization)?.result?.outcome??job.lostOutputFinalizationError;
  return `<tbody class="job" data-state="${escape(state)}" data-search="${escape(search)}">
    <tr class="summary-row">
      <th scope="row"><a href="#${id}">${escape(intent)}</a><span class="resource">${escape(job.operation?.method ?? '')} ${escape(job.operation?.url ?? '')}</span></th>
      <td><span class="state">${escape(LABELS.get(state) ?? state)}</span></td>
      <td>${code(outcome)}${observed ? '<span class="source-label">Original SF52</span>' : recovery.observationStatus ? '<span class="source-label">Original evidence</span>' : original.status ? '<span class="source-label">Original buyer</span>' : ''}${accounting?'<span class="source-label">Accounting: '+escape(accounting)+'</span>':''}</td>
      <td>${code(output?.status)}${output?.bytes !== undefined ? `<span class="source-label">${escape(output.bytes)} bytes</span>` : ''}${!original.responseFile && recovery.deliveryFile ? '<span class="source-label">Recovery record</span>' : ''}</td>
      <td>${code(job.attempt?.startedAt ?? job.createdAt)}<span class="source-label">${job.attempt?.startedAt ? 'Attempt started' : 'Queued'}</span></td>
    </tr>
    <tr class="detail-row"><td colspan="5"><details id="${id}"><summary>Request, result and recovery details</summary>${detail(job, queueRoot, commandFor, accountingWorkspace)}</details></td></tr>
  </tbody>`;
}

