      const pinned = {...cfg, operation:{...op,
        ...(body === null ? {} : {bodyFile:join(destination, 'request-body.bin')}),
        ...(ticket ? {ticketFile:join(destination, 'operation-ticket.json')} : {})}};
      const executionRaw = encoded(pinned);
