    schema:CROSSREF_DOCUMENT_SCHEMA, filename:filename(input.filename), role,
    sourceUrl:sourceUrl(input.sourceUrl, role === 'source'), retrievedAt, provenance,
    bodyBytes:bytes.length, bodySha256
